svg.script:

(function() {
  var activeScene = 'spine';
  var deLeeStation = 0;
  var isLight = false;

  window.a12p10h_selectScene = function(scene) {
    activeScene = scene;

    // Update Buttons
    var btnSpine = document.getElementById('a12p10h-btn-mode-spine');
    var btnTuber = document.getElementById('a12p10h-btn-mode-tuber');
    var btnPudendal = document.getElementById('a12p10h-btn-mode-pudendal');

    if (btnSpine) btnSpine.classList.remove('active');
    if (btnTuber) btnTuber.classList.remove('active');
    if (btnPudendal) btnPudendal.classList.remove('active');

    if (scene === 'spine' && btnSpine) btnSpine.classList.add('active');
    if (scene === 'tuber' && btnTuber) btnTuber.classList.add('active');
    if (scene === 'pudendal' && btnPudendal) btnPudendal.classList.add('active');

    // Update Anatomical Overlays & Lines
    var lineSpine = document.getElementById('a12p10h-line-biespinha');
    var lineTuber = document.getElementById('a12p10h-line-bituberoso');
    var groupPudendal = document.getElementById('a12p10h-label-pudendal');

    if (lineSpine) lineSpine.className.baseVal = (scene === 'spine' || scene === 'all') ? 'a12p10h-view-group' : 'a12p10h-view-group a12p10h-hidden';
    if (lineTuber) lineTuber.className.baseVal = (scene === 'tuber' || scene === 'all') ? 'a12p10h-view-group' : 'a12p10h-view-group a12p10h-hidden';
    if (groupPudendal) groupPudendal.style.opacity = (scene === 'pudendal') ? '1' : '0.4';

    // Panel Title & Badge
    var pTitle = document.getElementById('a12p10h-panel-title');
    var pBadgeBg = document.getElementById('a12p10h-panel-badge-bg');
    var pBadgeText = document.getElementById('a12p10h-panel-badge-text');
    var pBody = document.getElementById('a12p10h-detail-body');

    if (scene === 'spine') {
      if (pTitle) { pTitle.textContent = 'ESPINHA ISQUIÁTICA (ESTREITO MÉDIO)'; pTitle.setAttribute('fill', 'var(--a12p10h-spine-color, #00f5d4)'); }
      if (pBadgeBg) pBadgeBg.setAttribute('fill', 'var(--a12p10h-green-normal, #2ec4b6)');
      if (pBadgeText) pBadgeText.textContent = '10,5 cm · NORMAL';
      if (pBody) {
        pBody.innerHTML = '<tspan x="12" dy="0" fill="var(--a12p10h-spine-color, #00f5d4)" font-weight="700">DICA DE PROVA RESIDÊNCIA:</tspan>' +
                          '<tspan x="12" dy="16">Ao toque vaginal, a <tspan fill="#ffffff" font-weight="700">espinha isquiática</tspan> é o ponto de referência central.</tspan>' +
                          '<tspan x="12" dy="14">Bico pontiagudo medido no diâmetro biespinha (10,5 cm).</tspan>' +
                          '<tspan x="12" dy="14">Marca o Plano 0 de De Lee e o Estreito Médio pélvico.</tspan>';
      }
    } else if (scene === 'tuber') {
      if (pTitle) { pTitle.textContent = 'TUBEROSIDADE ISQUIÁTICA (SAÍDA)'; pTitle.setAttribute('fill', 'var(--a12p10h-tuber-color, #ff9f1c)'); }
      if (pBadgeBg) pBadgeBg.setAttribute('fill', 'var(--a12p10h-tuber-color, #ff9f1c)');
      if (pBadgeText) pBadgeText.textContent = '11,0 cm · SAÍDA';
      if (pBody) {
        pBody.innerHTML = '<tspan x="12" dy="0" fill="var(--a12p10h-tuber-color, #ff9f1c)" font-weight="700">ANATOMIA DA TUBEROSIDADE:</tspan>' +
                          '<tspan x="12" dy="16">Bloco rombo espesso, palpado externamente nas nádegas.</tspan>' +
                          '<tspan x="12" dy="14">Mede o diâmetro bituberoso (11,0 cm) no Estreito Inferior.</tspan>' +
                          '<tspan x="12" dy="14">Ponto de apoio do corpo ao sentar &amp; limite inferior do parto.</tspan>';
      }
    } else if (scene === 'pudendal') {
      if (pTitle) { pTitle.textContent = 'BLOQUEIO DO NERVO PUDENDO'; pTitle.setAttribute('fill', 'var(--a12p10h-nerve-color, #ffe600)'); }
      if (pBadgeBg) pBadgeBg.setAttribute('fill', 'var(--a12p10h-warn-yellow, #ffb703)');
      if (pBadgeText) pBadgeText.textContent = 'ANESTESIA LOCAL';
      if (pBody) {
        pBody.innerHTML = '<tspan x="12" dy="0" fill="var(--a12p10h-nerve-color, #ffe600)" font-weight="700">TÉCNICA DE BLOQUEIO DO PUDENDO:</tspan>' +
                          '<tspan x="12" dy="16">1. Palpar a espinha isquiática por via transvaginal.</tspan>' +
                          '<tspan x="12" dy="14">2. Perfurar o ligamento sacroespinhal medial/posterior à espinha.</tspan>' +
                          '<tspan x="12" dy="14">3. Injetar anestésico no forame isquiático menor.</tspan>';
      }
    }
  };

  window.a12p10h_setDeLee = function(st) {
    deLeeStation = st;
    var fetalGroup = document.getElementById('a12p10h-fetal-head');
    var fetalLabel = document.getElementById('a12p10h-fetal-label');
    var deLeeDesc = document.getElementById('a12p10h-delee-desc');

    // Y base for 0 cm is 340. Each cm corresponds to ~20px shift
    var yPos = 340 + (st * 20);
    if (fetalGroup) {
      fetalGroup.setAttribute('transform', 'translate(340, ' + yPos + ')');
    }

    var labelStr = (st > 0 ? '+' + st : st) + ' cm';
    if (st === 0) labelStr = '0 cm (Espinha)';
    if (fetalLabel) fetalLabel.textContent = 'Apresentação: ' + labelStr;

    if (deLeeDesc) {
      if (st < 0) {
        deLeeDesc.textContent = 'Estação ' + st + ' cm: Apresentação alta (acima das Espinhas Isquiáticas).';
        deLeeDesc.setAttribute('fill', 'var(--a12p10h-warn-yellow, #ffb703)');
      } else if (st === 0) {
        deLeeDesc.textContent = 'Estação 0: Vértice fetal no nível exato das Espinhas Isquiáticas (Insinuação).';
        deLeeDesc.setAttribute('fill', 'var(--a12p10h-spine-color, #00f5d4)');
      } else {
        deLeeDesc.textContent = 'Estação +' + st + ' cm: Apresentação desceu (aproximando-se do Estreito Inferior).';
        deLeeDesc.setAttribute('fill', 'var(--a12p10h-green-normal, #2ec4b6)');
      }
    }
  };

  window.a12p10h_toggleTheme = function() {
    var root = document.getElementById('a12p10h-root');
    isLight = !isLight;
    if (root) {
      if (isLight) {
        root.setAttribute('data-theme', 'light');
      } else {
        root.removeAttribute('data-theme');
      }
    }
  };
})();
